macro_rules! log{($($arg:tt)*)=>{let _=format!($($arg)*);};}
#[path="../../../src/installer_io.rs"]mod installer_io;
#[path="../../../src/installer.rs"]mod installer;
mod scan{pub fn valid_tid(t:&str)->bool{t.len()==9&&t.starts_with("PPSA")&&t[4..].bytes().all(|b|b.is_ascii_digit())}pub struct Source{pub title_id:String,pub drive:String}}
mod cache{pub fn peek_pkg(p:&std::path::Path)->std::io::Result<(String,String,String)>{let b=std::fs::read(p)?;if !b.starts_with(b"PPSA12345"){return Err(std::io::Error::other("Unsupported synthetic PKG"));}Ok(("PPSA12345".into(),"Synthetic package".into(),"1".into()))}}
mod storage{use std::sync::atomic::{AtomicU64,Ordering};pub static FREE:AtomicU64=AtomicU64::new(1<<30);pub struct Drive{pub mount:String,pub kind:&'static str,pub label:String,pub free:u64}pub fn drives()->Vec<Drive>{vec![Drive{mount:"/data".into(),kind:"internal",label:"Internal".into(),free:FREE.load(Ordering::SeqCst)},Drive{mount:"/tmp/titan-installer-external".into(),kind:"usb",label:"USB".into(),free:1<<30}]}}
mod web{use std::sync::{Mutex,atomic::{AtomicBool,Ordering}};pub struct Game{pub src:crate::scan::Source}pub struct State{pub games:Mutex<Vec<Game>>,pub paused:AtomicBool}impl State{pub fn wake(&self){}pub fn paused(&self)->bool{self.paused.load(Ordering::SeqCst)}}}
#[cfg(test)]mod tests{use super::*;use std::{fs,path::Path,sync::{Mutex,atomic::{AtomicBool,Ordering}}};static LOCK:Mutex<()>=Mutex::new(());
fn setup()->(std::path::PathBuf,web::State){let root=Path::new("/tmp/titan-installer-external");let _=fs::remove_dir_all(root);let _=fs::remove_dir_all(installer::ROOT);fs::create_dir_all(root).unwrap();let src=root.join("game.pkg");fs::write(&src,b"PPSA12345 synthetic game bytes").unwrap();storage::FREE.store(1<<30,Ordering::SeqCst);(src,web::State{games:Mutex::new(Vec::new()),paused:AtomicBool::new(false)})}
#[test]fn successful_install_preserves_external_and_refuses_existing_destination(){let _g=LOCK.lock().unwrap();let(src,state)=setup();let i=installer::Installer::default();i.queue(src.clone()).unwrap();assert!(i.queue(src.clone()).is_err());i.run(&state);assert_eq!(i.status()["phase"],"complete");let dest=Path::new(installer::ROOT).join("PPSA12345/PPSA12345.pkg");assert_eq!(fs::read(&src).unwrap(),fs::read(&dest).unwrap());assert_eq!(installer::roots().len(),1);i.queue(src.clone()).unwrap();i.run(&state);assert_eq!(i.status()["phase"],"error");assert_eq!(fs::read(&src).unwrap(),fs::read(&dest).unwrap());fs::remove_file(&dest).unwrap();installer::forget_empty(&dest).unwrap();assert!(!dest.parent().unwrap().exists());i.queue(src).unwrap();i.run(&state);assert_eq!(i.status()["phase"],"complete");}
#[test]fn cancellation_low_space_and_running_game_preserve_source(){let _g=LOCK.lock().unwrap();let(src,state)=setup();let i=installer::Installer::default();i.queue(src.clone()).unwrap();i.cancel();i.run(&state);assert_eq!(i.status()["phase"],"error");assert!(!Path::new(installer::ROOT).join("PPSA12345").exists());storage::FREE.store(0,Ordering::SeqCst);i.queue(src.clone()).unwrap();i.run(&state);assert!(i.status()["error"].as_str().unwrap().contains("storage"));assert!(src.is_file());storage::FREE.store(1<<30,Ordering::SeqCst);state.paused.store(true,Ordering::SeqCst);i.queue(src.clone()).unwrap();i.run(&state);assert_eq!(i.status()["phase"],"error");assert!(src.is_file());assert!(installer::roots().is_empty());}
#[test]fn external_browser_rejects_traversal_symlinks_and_internal_paths(){let _g=LOCK.lock().unwrap();let(src,_)=setup();assert!(installer::external(Path::new("/etc/passwd"),false).is_err());assert!(installer::external(Path::new("/tmp/titan-installer-external/../game.pkg"),false).is_err());let link=src.parent().unwrap().join("link.pkg");std::os::unix::fs::symlink(&src,&link).unwrap();assert!(installer::external(&link,false).is_err());let v=installer::browse("/tmp/titan-installer-external").unwrap();assert_eq!(v["entries"].as_array().unwrap().len(),1);}
}
